using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;using V15Voice;
public static class Lite412UiTests {
 static int n,code;static object F(object o,string name){return o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string name,params object[] a){return o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Check(bool yes,string why){if(!yes)throw new Exception(why);n++;Console.WriteLine("PASS "+why);}
 static string Srt(string dir,string name,string words){Directory.CreateDirectory(dir);string p=Path.Combine(dir,name);File.WriteAllText(p,"1\n00:00:00,000 --> 00:00:03,200\n"+words+"\n");return p;}
 static bool Fits(Control c){if(!c.Visible)return false;var r=c.RectangleToScreen(c.ClientRectangle);for(var p=c.Parent;p!=null;p=p.Parent)if(!p.RectangleToScreen(p.ClientRectangle).Contains(r))return false;return true;}
 static void Capture(Form f,string name){Application.DoEvents();f.Refresh();using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.Location,Point.Empty,f.Size);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation",name+".png"));}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=async(s,e)=>{try{
  var tabs=(TabControl)F(f,"tabs");var batch=(TabPage)F(f,"batchPage");var grid=(DataGridView)F(f,"jobGrid");Check(tabs.TabCount==7&&!tabs.TabPages.Cast<TabPage>().Any(p=>p.Text.Contains("Creator")),"Creator/video packaging page is absent; the original seven voice/subtitle pages remain");Check(f.GetType().Assembly.GetType("V15Voice.CreatorPipeline")==null&&f.GetType().Assembly.GetType("V15Voice.CreatorReceipt")==null,"Creator export and WAV receipt code are removed from the compiled app");Check(((Control)F(f,"batchTools")).Controls.Find("batchFolderImport",true).Any()&&((Control)F(f,"batchTools")).Controls.Find("batchSelectFiles",true).Any(),"Batch exposes folder import and quick selection beside existing file import");
  string root=Path.Combine(Path.GetTempPath(),"fast UI "+Guid.NewGuid().ToString("N"));string source=Srt(root,"story.srt","A mysterious shadow whispered about an eerie secret.");Srt(Path.Combine(root,"sub"),"other.srt","This story keeps every source word in order.");Srt(root,"story.final.srt","An output not a fresh source.");
  await(Task)Call(f,"ImportBatchInputs",(object)new[]{root});var jobs=(List<BatchJob>)F(f,"jobs");Check(jobs.Count==2&&tabs.SelectedTab==batch,"Native async folder import loads two source scripts and opens the existing batch page");Check(jobs.All(j=>j.Cues.Count==1)&&!jobs.Any(j=>j.InputPath.EndsWith(".final.srt")),"Native folder import excludes generated SRT without changing source text");
  var pane=f.Controls.Find("batchVoiceAdvice",true).First();var suggestions=BeoTheme.Walk(pane).OfType<BeoButton>().Where(b=>b.Tag is VoiceSuggestion).ToArray();Check(suggestions.Length>0&&BeoTheme.Walk(pane).OfType<Label>().Any(l=>l.Text.Contains("chưa đo")),"Import immediately shows named voice recommendations and explicitly says they are unmeasured");Check(!File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"auto-tts-called")),"Import and recommendation never execute the available synthetic TTS executable");
  var pick=suggestions.First(b=>b.Enabled);var profile=((VoiceSuggestion)pick.Tag).Profile;pick.PerformClick();Check(((ComboBox)F(f,"voices")).SelectedItem.ToString().Contains(profile.Name),"A suggested installed voice can be applied with one click");Check(jobs[0].Cues[0].Text=="A mysterious shadow whispered about an eerie secret.","Applying a voice recommendation does not rewrite the script");
  Call(f,"LoadFile",source);Check(BeoTheme.Walk(f.Controls.Find("studioVoiceAdvice",true).First()).OfType<BeoButton>().Any(b=>b.Tag is VoiceSuggestion),"A single imported source also gets automatic suggestions in Studio");tabs.SelectedTab=batch;
  jobs[0].State=JobState.Done;Call(f,"SelectBatchFiles",1);Check(!jobs[0].Selected&&jobs[1].Selected,"Choose unfinished selects failed/pending work while leaving completed files unchecked");Call(f,"SelectBatchFiles",0);Check(jobs.All(j=>j.Selected),"Select all restores the whole batch in one action");Call(f,"SelectBatchFiles",2);Check(jobs.All(j=>!j.Selected),"Unselect all is available without deleting queue data");Call(f,"SelectBatchFiles",0);jobs[0].State=JobState.Running;jobs[0].Progress.Begin();jobs[0].Progress.Update(47,"actual test progress");Call(f,"RefreshJobs");var row=grid.Rows[0];long before=(long)F(f,"fullQueueRebuilds");
  for(int i=0;i<10000;i++)Call(f,"PublishRenderUi",i%100,"progress event "+i);Call(f,"PublishRenderUi",47,"Latest TTS state");Call(f,"FlushRenderUi");Check(Object.ReferenceEquals(row,grid.Rows[0])&&(long)F(f,"fullQueueRebuilds")==before,"Ten thousand render events update the actual queue without rebuilding any rows");Check(Convert.ToInt32(grid.Rows[0].Cells["completion"].Value)==47&&((Label)F(f,"status")).Text=="Latest TTS state","Coalesced progress preserves the final percent and most recent status");
  var font=(ComboBox)F(f,"beoFontPick");var theme=(ComboBox)F(f,"beoThemePick");foreach(var size in new[]{new Size(1440,960),new Size(1100,740)}){f.Size=size;f.Location=Point.Empty;foreach(int scale in new[]{0,2}){font.SelectedIndex=scale;Application.DoEvents();Check(Fits((Button)F(f,"runBatch"))&&Fits((Button)F(f,"beoBatchStop"))&&Fits(grid),"Batch actions and percentage table fit "+size+" font "+scale);}}
  foreach(var j in jobs)j.State=JobState.Done;Call(f,"RefreshBeoSummary");Check(((Button)F(f,"runBatch")).Enabled&&((Button)F(f,"runBatch")).Text.Contains("KIỂM TRA"),"Completed selected files can still be revalidated after a source/configuration/output change");foreach(var j in jobs){j.Progress.Restore(0,0,false);j.State=JobState.Queued;}Call(f,"RefreshJobs");font.SelectedIndex=0;f.Size=new Size(1440,960);theme.SelectedIndex=2;((Label)F(f,"status")).Text="DỮ LIỆU KIỂM THỬ · Gợi ý metadata, chưa đo giọng";Capture(f,"beo-lite-batch");tabs.SelectedIndex=0;Capture(f,"beo-lite-studio");tabs.SelectedTab=batch;
  var side=(FlowLayoutPanel)F(f,"beoBatchSide");Check(BeoTheme.Walk(side).OfType<Label>().Any(l=>l.Text=="Bộ cấu hình đã lưu"),"Saved voice configurations are accessible directly from the batch sidebar");Call(f,"SetBusy",true);Check(BeoTheme.Walk(pane).OfType<BeoButton>().All(b=>!b.Enabled),"Rendering disables voice suggestion actions without hiding the recommendations");Call(f,"CancelTasks");Check((bool)F(f,"batchUtilityCancelled"),"The shared stop action also cancels folder scanning/preflight");Call(f,"SetBusy",false);jobs[0].Progress.Finish(false);jobs[0].State=JobState.Queued;Call(f,"SaveSession");
  Check(((ComboBox)F(f,"workflowStudio")).Items.Count==1,"Lite retains only the source-file workflow");Check(!BeoTheme.Walk(f).OfType<Button>().Any(b=>b.Text.Contains("AI tự sửa")||b.Text.Contains("Cài / kiểm tra gói AI")),"Lite exposes no rewrite or language-model installation buttons");Check(!((DataGridView)F(f,"grid")).Columns.Contains("aiFix"),"Lite removes the inline AI repair column");Call(f,"ApplyWorkflowChoice",2);Check(((ComboBox)F(f,"workflowStudio")).SelectedIndex==0&&((VoiceSettings)Call(f,"CaptureSettings")).AiMode==0,"Old UI mode requests cannot re-enable automatic repair");Check(f.Text.Contains("Lite")&&f.GetType().Assembly.GetName().Version.ToString()=="4.1.2.0","Window identifies the Lite build");Console.WriteLine("TOTAL LITE412 UI "+n+" PASS · real WinForms on Mono/Xvfb; no GPU inference");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{Call(f,"SetBusy",false);f.Close();}};Application.Run(f);Environment.Exit(code);}
}
